styles=doc.styles; normal=styles['Normal']; normal.font.name='Times New Roman'; normal._element.rPr.rFonts.set(qn('w:ascii'),'Times New Roman'); normal.font.size=Pt(12); normal.paragraph_format.line_spacing=1.5
